//! Backend-neutral statement of where Hull code came from.
//!
//! Every Hull statement has an [`Origin`]: either a range of source text, or
//! "generated by the compiler for this reason". Annotated Yul, instruction
//! stamps in the Sonatina route and debug-info writers are different renderings
//! of the same function, [`stmt_origin`]. The origin is a value, not a key into
//! a table: it is a pure function of source positions and file URLs, so it
//! carries no arena index, interning id or counter.
//!
//! Spans stay anchor-relative inside Hull. [`Origin::resolve`] turns an origin
//! into absolute offsets and a file URL and is an output-edge operation: call
//! it from backend lowerings and listings, never from a tracked query.

use std::{collections::BTreeMap, fmt};

use hir::{
    Db as HirDb,
    ast::function::{YulStmt, YulStmtKind},
    input::SourceFile,
    span::Span,
};

use crate::ir::{Function, Object, Program, Stmt, StmtKind};

/// Why a piece of code exists although no source text says it.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum GeneratedReason {
    /// Contract entry code: deployment and runtime entry functions, and the
    /// statements that call them at object level.
    Entry,
    /// Storage slot helper functions.
    StorageHelper,
    /// Methods derived for an ADT.
    Derived,
    /// Helper functions for string and revert-message literals. They are
    /// shared by content, so no single use of the literal explains them.
    Literal,
}

impl GeneratedReason {
    const ALL: [Self; 4] = [
        Self::Entry,
        Self::StorageHelper,
        Self::Derived,
        Self::Literal,
    ];

    /// The spelling used in the wire form and in listings.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Entry => "entry",
            Self::StorageHelper => "storage-helper",
            Self::Derived => "derived",
            Self::Literal => "literal",
        }
    }

    fn from_name(name: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|reason| reason.as_str() == name)
    }
}

/// What a Hull statement or function will be attributed to.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Origin<'db> {
    /// Running this code carries out the text of this range.
    Source(Span<'db>),
    /// No source text says this; the compiler made it for the declaration at
    /// `context`. A generated origin explains the code but never attributes it
    /// to a range.
    Generated {
        reason: GeneratedReason,
        context: Span<'db>,
    },
}

/// The origin of `span` for a statement (Hull or inline Yul) inside `function`.
///
/// `function == None` means object-level code, which is always generated entry
/// code. Inside a function marked as generated, a statement located at the
/// function's own span is generated (the generators thread one span through
/// everything they build); a statement with any other span keeps it as source,
/// as when a generated wrapper inlines library statements.
pub fn stmt_origin<'db>(function: Option<&Function<'db>>, span: Span<'db>) -> Origin<'db> {
    match function {
        None => Origin::Generated {
            reason: GeneratedReason::Entry,
            context: span,
        },
        Some(function) => match function.generated {
            Some(reason) if span == function.span => Origin::Generated {
                reason,
                context: span,
            },
            _ => Origin::Source(span),
        },
    }
}

/// The origin of a function definition as a whole.
pub fn function_origin<'db>(function: &Function<'db>) -> Origin<'db> {
    match function.generated {
        Some(reason) => Origin::Generated {
            reason,
            context: function.span,
        },
        None => Origin::Source(function.span),
    }
}

/// An [`Origin`] with its span resolved to a file URL and absolute byte offsets.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ResolvedOrigin {
    /// `None` for source, the reason for generated code.
    pub generated: Option<GeneratedReason>,
    pub url: String,
    pub start: u32,
    pub end: u32,
}

impl<'db> Origin<'db> {
    /// Resolves the origin to absolute offsets, or `None` for a zero-width span.
    ///
    /// Edge-only, like [`Span::resolve_to_absolute`].
    pub fn resolve(&self, db: &'db dyn HirDb) -> Option<ResolvedOrigin> {
        let (generated, span) = match *self {
            Self::Source(span) => (None, span),
            Self::Generated { reason, context } => (Some(reason), context),
        };
        let absolute = span.resolve_to_absolute(db);
        if absolute.start == absolute.end {
            return None;
        }
        Some(ResolvedOrigin {
            generated,
            url: absolute.file.url(db).as_str().to_owned(),
            start: absolute.start.as_u32(),
            end: absolute.end.as_u32(),
        })
    }
}

/// A string that is not the wire form of a [`ResolvedOrigin`].
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OriginParseError {
    message: String,
}

impl OriginParseError {
    fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }

    pub fn message(&self) -> &str {
        &self.message
    }
}

impl fmt::Display for OriginParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.message)
    }
}

impl std::error::Error for OriginParseError {}

impl ResolvedOrigin {
    /// The wire form: `s <start> <end> <url>` for source and
    /// `g <reason> <start> <end> <url>` for generated code.
    ///
    /// The URL comes last so that it may contain any character. This function
    /// and [`ResolvedOrigin::parse`] are the only code that writes or splits
    /// the string.
    pub fn encode(&self) -> String {
        match self.generated {
            None => format!("s {} {} {}", self.start, self.end, self.url),
            Some(reason) => format!(
                "g {} {} {} {}",
                reason.as_str(),
                self.start,
                self.end,
                self.url
            ),
        }
    }

    /// Parses the wire form written by [`ResolvedOrigin::encode`].
    ///
    /// Anything else is rejected: other tags, missing or extra fields, an
    /// unknown reason, an empty URL, an empty or inverted range, and number
    /// spellings that `encode` does not produce.
    pub fn parse(s: &str) -> Result<Self, OriginParseError> {
        let (tag, rest) = s
            .split_once(' ')
            .ok_or_else(|| OriginParseError::new(format!("origin `{s}` has no fields")))?;
        let (generated, fields) = match tag {
            "s" => (None, rest.splitn(3, ' ').collect::<Vec<_>>()),
            "g" => {
                let fields = rest.splitn(4, ' ').collect::<Vec<_>>();
                let reason = GeneratedReason::from_name(fields[0]).ok_or_else(|| {
                    OriginParseError::new(format!("unknown generated reason `{}`", fields[0]))
                })?;
                (Some(reason), fields[1..].to_vec())
            }
            _ => {
                return Err(OriginParseError::new(format!(
                    "origin tag `{tag}` is neither `s` nor `g`"
                )));
            }
        };
        let &[start, end, url] = fields.as_slice() else {
            return Err(OriginParseError::new(format!(
                "origin `{s}` has too few fields"
            )));
        };
        let number = |text: &str| {
            text.parse::<u32>()
                .map_err(|_| OriginParseError::new(format!("invalid offset `{text}` in `{s}`")))
        };
        let parsed = Self {
            generated,
            url: url.to_owned(),
            start: number(start)?,
            end: number(end)?,
        };
        if parsed.url.is_empty() {
            return Err(OriginParseError::new(format!("origin `{s}` has no URL")));
        }
        if parsed.start >= parsed.end {
            return Err(OriginParseError::new(format!(
                "origin `{s}` has an empty or inverted range"
            )));
        }
        if parsed.encode() != s {
            return Err(OriginParseError::new(format!(
                "origin `{s}` is not in canonical form"
            )));
        }
        Ok(parsed)
    }
}

/// The source files named by a program's origins, numbered by sorted URL.
///
/// Ids are positions in the list of distinct file URLs sorted as strings, so
/// they are a function of the program's sources and do not depend on the order
/// in which a backend visits statements. Every backend and debug-info writer
/// shares one table so that ids agree.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceTable {
    entries: Vec<(String, SourceFile)>,
}

impl SourceTable {
    /// Collects the files of every function, statement and inline Yul
    /// statement span in `program`. Zero-width spans are skipped: they resolve
    /// to no origin, so no origin can name their file.
    ///
    /// Edge-only, like [`Span::resolve_to_absolute`].
    pub fn from_program<'db>(db: &'db dyn HirDb, program: &Program<'db>) -> Self {
        let mut files = BTreeMap::<String, SourceFile>::new();
        let mut visit = |span: Span<'db>| {
            if span.begin() == span.end() {
                return;
            }
            let file = span.source_file(db);
            let url = file.url(db).as_str();
            if !files.contains_key(url) {
                files.insert(url.to_owned(), file);
            }
        };
        for function in &program.functions {
            function_spans(function, &mut visit);
        }
        for object in &program.objects {
            object_spans(object, &mut visit);
        }
        Self {
            entries: files.into_iter().collect(),
        }
    }

    /// The id of the file with this URL, if the table has it.
    pub fn id(&self, url: &str) -> Option<u32> {
        self.entries
            .binary_search_by(|(entry, _)| entry.as_str().cmp(url))
            .ok()
            .map(|index| index as u32)
    }

    /// `(id, url, file)` in id order.
    pub fn entries(&self) -> impl Iterator<Item = (u32, &str, SourceFile)> {
        self.entries
            .iter()
            .enumerate()
            .map(|(index, (url, file))| (index as u32, url.as_str(), *file))
    }
}

/// Calls `visit(function, stmt, depth)` for each statement of `stmts` and, after
/// it, for the statements nested in it. `depth` is 0 for `stmts` and grows by
/// one per level of nesting. `function` is the Hull function the statements
/// belong to, or `None` for object-level code.
pub(crate) fn walk_stmts<'db>(
    function: Option<&Function<'db>>,
    stmts: &[Stmt<'db>],
    depth: usize,
    visit: &mut impl FnMut(Option<&Function<'db>>, &Stmt<'db>, usize),
) {
    for stmt in stmts {
        visit(function, stmt, depth);
        match &stmt.kind {
            StmtKind::Block(body) => walk_stmts(function, body, depth + 1, visit),
            StmtKind::For {
                init, post, body, ..
            } => {
                for nested in [init, post, body] {
                    walk_stmts(function, nested, depth + 1, visit);
                }
            }
            StmtKind::Match { alts, .. } => {
                for alt in alts {
                    walk_stmts(function, &alt.body, depth + 1, visit);
                }
            }
            StmtKind::Let { .. }
            | StmtKind::Assign { .. }
            | StmtKind::Expr(_)
            | StmtKind::Return(_)
            | StmtKind::Break
            | StmtKind::Continue
            | StmtKind::Assembly(_)
            | StmtKind::Revert(_)
            | StmtKind::Comment(_) => {}
        }
    }
}

fn object_spans<'db>(object: &Object<'db>, visit: &mut impl FnMut(Span<'db>)) {
    for function in &object.code.functions {
        function_spans(function, visit);
    }
    walk_stmts(None, &object.code.stmts, 0, &mut |_, stmt, _| {
        stmt_spans(stmt, visit)
    });
    for inner in &object.inners {
        object_spans(inner, visit);
    }
}

fn function_spans<'db>(function: &Function<'db>, visit: &mut impl FnMut(Span<'db>)) {
    visit(function.span);
    walk_stmts(Some(function), &function.body, 0, &mut |_, stmt, _| {
        stmt_spans(stmt, visit)
    });
}

fn stmt_spans<'db>(stmt: &Stmt<'db>, visit: &mut impl FnMut(Span<'db>)) {
    visit(stmt.span);
    if let StmtKind::Assembly(body) = &stmt.kind {
        yul_stmts_spans(body, visit);
    }
}

fn yul_stmts_spans<'db>(stmts: &[YulStmt<'db>], visit: &mut impl FnMut(Span<'db>)) {
    for stmt in stmts {
        visit(stmt.span);
        match &stmt.kind {
            YulStmtKind::Block(body)
            | YulStmtKind::If { body, .. }
            | YulStmtKind::FunctionDef { body, .. } => yul_stmts_spans(body, visit),
            YulStmtKind::For {
                init, post, body, ..
            } => {
                yul_stmts_spans(init, visit);
                yul_stmts_spans(post, visit);
                yul_stmts_spans(body, visit);
            }
            YulStmtKind::Switch { cases, default, .. } => {
                for case in cases {
                    yul_stmts_spans(&case.body, visit);
                }
                if let Some(default) = default {
                    yul_stmts_spans(default, visit);
                }
            }
            YulStmtKind::Let { .. }
            | YulStmtKind::Assign { .. }
            | YulStmtKind::Expr(_)
            | YulStmtKind::Leave
            | YulStmtKind::Break
            | YulStmtKind::Continue
            | YulStmtKind::Error => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use hir::{
        diag::Offset,
        input::SourceFile,
        span::{AnchorId, Span},
    };
    use solcore_test_utils::define_frontend_test_db;

    use super::*;
    use crate::ir::{Arg, Expr, Ty};

    define_frontend_test_db!(TestDb, hir_ty);

    fn file(db: &TestDb, url: &str) -> SourceFile {
        SourceFile::new(db, url.parse().expect("valid URL"), Some("x".repeat(64)))
    }

    fn span<'db>(db: &'db TestDb, file: SourceFile, begin: u32, end: u32) -> Span<'db> {
        Span::new(
            AnchorId::root(db, file),
            Offset::new(begin),
            Offset::new(end),
        )
    }

    fn function<'db>(
        name: &str,
        fn_span: Span<'db>,
        generated: Option<GeneratedReason>,
        stmt_spans: &[Span<'db>],
    ) -> Function<'db> {
        let word = Ty::word(fn_span);
        Function {
            span: fn_span,
            generated,
            name: name.into(),
            args: vec![Arg {
                span: fn_span,
                name: "x".into(),
                ty: word.clone(),
            }],
            ret: word.clone(),
            body: stmt_spans
                .iter()
                .map(|&span| Stmt {
                    span,
                    kind: StmtKind::Return(Expr::var(span, "x", word.clone())),
                })
                .collect(),
        }
    }

    fn program<'db>(functions: Vec<Function<'db>>, span: Span<'db>) -> Program<'db> {
        Program {
            span,
            entry_points: Vec::new(),
            functions,
            objects: Vec::new(),
        }
    }

    #[test]
    fn origin_wire_form_round_trips() {
        let odd_url = "file:///tmp/a dir/with space|and|pipe/m.sol";
        for generated in std::iter::once(None).chain(GeneratedReason::ALL.map(Some)) {
            for url in ["memory:///m.sol", odd_url, "x y  z"] {
                let origin = ResolvedOrigin {
                    generated,
                    url: url.to_owned(),
                    start: 3,
                    end: 4_000_000_000,
                };
                let text = origin.encode();
                assert_eq!(ResolvedOrigin::parse(&text), Ok(origin), "{text}");
            }
        }
        assert_eq!(
            ResolvedOrigin {
                generated: None,
                url: odd_url.to_owned(),
                start: 1,
                end: 2,
            }
            .encode(),
            "s 1 2 file:///tmp/a dir/with space|and|pipe/m.sol"
        );
        assert_eq!(
            ResolvedOrigin {
                generated: Some(GeneratedReason::StorageHelper),
                url: "memory:///m.sol".to_owned(),
                start: 7,
                end: 9,
            }
            .encode(),
            "g storage-helper 7 9 memory:///m.sol"
        );
    }

    #[test]
    fn origin_parse_rejects_anything_else() {
        for text in [
            "",
            "s",
            "s 1 2",
            "s 1 2 ",
            "g entry 1 2",
            "g entry 1",
            "g 1 2 memory:///m.sol",
            "x 1 2 memory:///m.sol",
            "s a 2 memory:///m.sol",
            "s 1 b memory:///m.sol",
            "s -1 2 memory:///m.sol",
            "s +1 2 memory:///m.sol",
            "s 01 2 memory:///m.sol",
            "s 2 2 memory:///m.sol",
            "s 3 2 memory:///m.sol",
            "s 1 4294967296 memory:///m.sol",
            "g unknown 1 2 memory:///m.sol",
            "g entry  1 2 memory:///m.sol",
            " s 1 2 memory:///m.sol",
        ] {
            assert!(ResolvedOrigin::parse(text).is_err(), "accepted `{text}`");
        }
    }

    #[test]
    fn origin_follows_the_generated_rule_and_resolves_to_a_file_range() {
        let db = TestDb::default();
        let main = file(&db, "memory:///main.sol");
        let whole = span(&db, main, 0, 40);
        let inner = span(&db, main, 5, 9);

        let marked = function("m", whole, Some(GeneratedReason::StorageHelper), &[]);
        let unmarked = function("u", whole, None, &[]);

        assert_eq!(
            stmt_origin(None, inner),
            Origin::Generated {
                reason: GeneratedReason::Entry,
                context: inner
            }
        );
        assert_eq!(
            stmt_origin(Some(&marked), whole),
            Origin::Generated {
                reason: GeneratedReason::StorageHelper,
                context: whole
            }
        );
        assert_eq!(stmt_origin(Some(&marked), inner), Origin::Source(inner));
        assert_eq!(stmt_origin(Some(&unmarked), whole), Origin::Source(whole));
        assert_eq!(
            function_origin(&marked),
            Origin::Generated {
                reason: GeneratedReason::StorageHelper,
                context: whole
            }
        );
        assert_eq!(function_origin(&unmarked), Origin::Source(whole));

        // An origin resolves to its file and absolute range.
        assert_eq!(Origin::Source(span(&db, main, 4, 4)).resolve(&db), None);
        assert_eq!(
            Origin::Source(span(&db, main, 4, 9)).resolve(&db),
            Some(ResolvedOrigin {
                generated: None,
                url: "memory:///main.sol".to_owned(),
                start: 4,
                end: 9,
            })
        );
        assert_eq!(
            Origin::Generated {
                reason: GeneratedReason::Derived,
                context: span(&db, main, 1, 2)
            }
            .resolve(&db)
            .map(|resolved| resolved.encode()),
            Some("g derived 1 2 memory:///main.sol".to_owned())
        );
    }

    #[test]
    fn origin_source_tables_are_equal_and_sorted_by_url() {
        let db = TestDb::default();
        let zed = file(&db, "memory:///z.sol");
        let alpha = file(&db, "memory:///a.sol");
        let empty_only = file(&db, "memory:///empty.sol");
        let f1 = function(
            "f1",
            span(&db, zed, 0, 30),
            None,
            &[span(&db, zed, 2, 8), span(&db, alpha, 1, 3)],
        );
        let f2 = function(
            "f2",
            span(&db, alpha, 10, 20),
            Some(GeneratedReason::Derived),
            &[span(&db, empty_only, 5, 5)],
        );
        let top = span(&db, zed, 0, 1);

        let forward = program(vec![f1.clone(), f2.clone()], top);
        let table = SourceTable::from_program(&db, &forward);
        assert_eq!(table, SourceTable::from_program(&db, &forward));

        // Visiting order does not change ids.
        let reversed = program(vec![f2, f1], top);
        assert_eq!(table, SourceTable::from_program(&db, &reversed));

        let entries = table
            .entries()
            .map(|(id, url, entry)| (id, url.to_owned(), entry))
            .collect::<Vec<_>>();
        assert_eq!(
            entries,
            vec![
                (0, "memory:///a.sol".to_owned(), alpha),
                (1, "memory:///z.sol".to_owned(), zed)
            ]
        );
        assert_eq!(table.id("memory:///a.sol"), Some(0));
        assert_eq!(table.id("memory:///z.sol"), Some(1));
        // A file seen only through zero-width spans, and an unknown file.
        assert_eq!(table.id("memory:///empty.sol"), None);
        assert_eq!(table.id("memory:///other.sol"), None);
    }
}
